import{z as n,x as B,o as i,c as d,q as s,j as l,D as t,d as r,s as o,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"eBPF 观测","description":"","frontmatter":{"title":"eBPF 观测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ebpf-observability.md","filePath":"cs/ebpf-observability.md","lastUpdated":1791413859000}'),A={name:"cs/ebpf-observability.md"};function c(m,a,f,P,b,h){const p=B("Mermaid");return i(),d("div",null,[a[2]||(a[2]=s('<h1 id="ebpf-观测" tabindex="-1">eBPF 观测 <a class="header-anchor" href="#ebpf-观测" aria-label="Permalink to &quot;eBPF 观测&quot;">​</a></h1><div class="epigraph"><p>观测用 BPF 挂在 tracepoint、kprobe、perf 事件上：在核内聚合进 map，用户只读摘要，避免每事件出核。</p><footer>—— 据 Linux bpf(2)；BCC/bpftrace 实践；[XDP](/cs/xdp-ebpf) 为数据面对照</footer></div><p><a href="/cs/perf-sampling">perf</a> 常把样本拷出核。<a href="/cs/ftrace-tracepoints">ftrace</a> 环也会满。缺口是 <strong>eBPF 观测</strong>：在事件处聚合。不是网络过滤重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>程序：读 <code>pt_regs</code>、pid、延迟，<code>map</code> 直方图。verifier 限制。缺口：CO-RE 可移植；与 <a href="/cs/sched-ext">sched_ext</a> 同引擎不同挂钩。本课不把 bpftrace 语法当语言课。</p><p><span class="marginnote">生产观测应优先 tracepoint 再 kprobe。对象是可验证的内核小程序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载 → attach → 事件触发 BPF → 更新 map → 用户轮询 map。对照 XDP：早丢包 vs 记直方图。对照 <a href="/cs/kernel-audit">audit</a>：audit 要合规原文，BPF 常只要统计。对照 ASan：编译插桩 vs 运行时挂接。</p><p><span class="marginnote">可以把它想象成把计算器搬进仓库：以前每个包裹（事件）都要寄到办公室（用户态）拆开统计，现在仓库门口就有一台计数器（map），一天结束只寄一张汇总单回去。高频系统里，「搬运」本身就是最大的开销，所以聚合位置比聚合算法更关键。</span></p>',9)),(i(),l(E,null,{default:t(()=>[o(p,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22tracepoint%2Fkprobe%2Fperf%22%5D%20--%3E%20BPF%5B%22eBPF%22%5D%0A%20%20BPF%20--%3E%20MAP%5B%22%E5%93%88%E5%B8%8C%2F%E7%9B%B4%E6%96%B9%E5%9B%BE%20map%22%5D%0A%20%20MAP%20--%3E%20USR%5B%22%E7%94%A8%E6%88%B7%E8%AF%BB%E6%91%98%E8%A6%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("eBPF 把观测从「搬运原始事件」变成「核内折减」，使生产系统可常开。verifier 是安全边界。不要写成 AIOps。与 "),e("a",{href:"/cs/memcg"},"memcg"),r("：map 占内核内存，要限额。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"verifier（验证器）本质是一段静态检查代码：加载前对每条指令做模拟执行，确认不会越界读内存、不会死循环、不会碰未授权指针，全通过了才放行进内核。它是 eBPF 敢在内核里跑第三方代码的全部底气——检查不通过，程序根本加载不进来。")],-1)),a[6]||(a[6]=e("p",null,"一段 BPF 程序从源码到真正生效，要过哪几关？",-1)),(i(),l(E,null,{default:t(()=>[o(p,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22BPF%20%E6%BA%90%E7%A0%81%22%5D%20--%3E%20LLVM%5B%22Clang%2FLLVM%20%E7%BC%96%E6%88%90%E5%AD%97%E8%8A%82%E7%A0%81%22%5D%0A%20%20LLVM%20--%3E%20VER%7B%22verifier%20%E6%A8%A1%E6%8B%9F%E6%89%A7%E8%A1%8C%E9%80%90%E6%9D%A1%E6%A3%80%E6%9F%A5%22%7D%0A%20%20VER%20--%3E%7C%22%E8%B6%8A%E7%95%8C%2F%E6%AD%BB%E5%BE%AA%E7%8E%AF%2F%E9%87%8E%E6%8C%87%E9%92%88%22%7C%20REJ%5B%22%E6%8B%92%E7%BB%9D%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20VER%20--%3E%7C%22%E5%85%A8%E9%83%A8%E9%80%9A%E8%BF%87%22%7C%20JIT%5B%22JIT%20%E7%BF%BB%E6%88%90%E6%9C%BA%E5%99%A8%E7%A0%81%22%5D%0A%20%20JIT%20--%3E%20ATT%5B%22attach%20%E5%88%B0%E6%8C%82%E9%92%A9%E7%82%B9%22%5D%0A%20%20ATT%20--%3E%20RUN%5B%22%E4%BA%8B%E4%BB%B6%E8%A7%A6%E5%8F%91%E6%97%B6%E6%A0%B8%E5%86%85%E8%BF%90%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p>错误 attach 高频繁点仍可打满 CPU。</p><p><span class="marginnote">初学者容易以为「用了 eBPF 就近零开销」。实际上每次事件触发都要执行 BPF 指令并更新 map，若挂在每秒上百万次的路径上，CPU 照样被打满。正确顺序是：先看挂钩点的触发频率，再谈观测方案的成本。</span></p><p>实现上：CO-RE 靠 BTF 把字段偏移从编译时解开。map 大小计入内核内存，要 ulimit/memcg。attach 到高频 kprobe 仍能把 CPU 打满，优先 tracepoint。 读法上只引用<a href="/cs/perf-sampling">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>eBPF 观测</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 helper。不保证稳定 attach 点 ABI——后课 kABI。下一课崩溃转储：kdump。</p><p>版本字段会变，课序钉的是机制对象「eBPF 观测」，不是某一主线内核的结构体名。 后课默认：可在核内用 BPF 聚合事件。崩溃转储 kdump/crash，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>观测 BPF 在事件处聚合到 map。</li><li>比全量出核便宜；挂钩点选择决定税。</li><li>kdump 是下一课。</li><li>出处：bpf(2)；BCC；内核 BPF 文档。</li></ul>',10))])}const C=n(A,[["render",c]]);export{u as __pageData,C as default};
